/* All countries, resources and outcomes are fictional teaching constructs. */
const Lab = (() => {
 const countries = [
  {id:'k',name:'Kitala',initial:'KT',color:'#dd9d60',tag:'Access & equity',role:'Your delegation',pop:18,need:40,budget:20,desc:'An import-dependent country facing the highest immediate need. Your public health network can distribute doses, but financing is limited.',public:'Prioritize countries with the greatest health need.',private:'Secure at least 30% of the pooled doses and at least 25 million credits of donor support. Your cabinet will accept transparent delivery reporting.',line:'We need an allocation that follows health need, backed by funding we can actually use.'},
  {id:'n',name:'Nordland',initial:'NO',color:'#80aeb9',tag:'Finance & accountability',pop:12,need:15,budget:80,desc:'A major donor with fiscal capacity and a parliament demanding evidence that international spending delivers results.',public:'Support a funded, accountable international response.',private:'Accept donor financing up to 45 million credits only with quarterly public reporting and at least 15% of pooled doses.',line:'Solidarity needs an accountable delivery plan. Our parliament will ask where every commitment goes.'},
  {id:'m',name:'Meridia',initial:'ME',color:'#aba0ca',tag:'Production & certainty',pop:30,need:25,budget:45,desc:'A manufacturing country balancing international supply commitments with domestic demand and production costs.',public:'Keep production viable and delivery commitments predictable.',private:'Require at least 25% of pooled doses and a production guarantee. If supply falls, require at least 30%.',line:'We can sustain production, but we need purchase certainty and a defensible domestic allocation.'},
  {id:'p',name:'Pelagia',initial:'PE',color:'#9bbf8d',tag:'Delivery & resilience',pop:8,need:20,budget:15,desc:'An island federation where last-mile transport and cold-chain capacity are essential to reaching remote communities.',public:'Make access meaningful for remote and underserved communities.',private:'Require at least 15% of pooled doses and at least 10 million credits of delivery support.',line:'A shipment at the port is not a vaccine in someone’s arm. Delivery must be part of the agreement.'}
 ];
 const fresh=mode=>({mode,stage:0,tab:'brief',supply:100,shock:false,briefed:false,offers:0,selected:'k',alloc:[25,25,25,25],fund:20,delivery:5,report:false,guarantee:false,consulted:[],votes:{},history:[],adopted:false,decided:false,implementation:[10,5,5],reflection:'',finished:false});
 function position(s,i){const a=s.alloc[i];if(i===0)return {yes:a>=30&&s.fund>=25,reason:a<30?'Needs at least 30% of pooled doses.':s.fund<25?'Needs at least 25m credits of donor financing.':'Access and financing requirements are met.'};if(i===1)return {yes:s.report&&s.fund<=45&&a>=15,reason:!s.report?'Requests quarterly public reporting.':s.fund>45?'Financing exceeds its 45m-credit mandate.':a<15?'Needs at least 15% of pooled doses.':'Financing is within mandate and accountable.'};if(i===2)return {yes:s.guarantee&&a>=(s.shock?30:25),reason:!s.guarantee?'Requests a production purchase guarantee.':a<(s.shock?30:25)?`Needs at least ${s.shock?30:25}% of pooled doses.`:'Production and allocation requirements are met.'};return {yes:a>=15&&s.delivery>=10,reason:a<15?'Needs at least 15% of pooled doses.':s.delivery<10?'Needs at least 10m credits of delivery support.':'Allocation and delivery requirements are met.'};}
 function valid(s){return s.alloc.reduce((a,b)=>a+b,0)===100&&s.delivery<=s.fund;}
 function outcome(s){const [cold,teams,data]=s.implementation;const budget=20+s.fund-s.delivery;const spent=cold+teams+data;const readiness=Math.min(1,.3+Math.min(cold,20)*.015+Math.min(teams,20)*.015+Math.min(data,10)*.01);const received=s.adopted?s.supply*s.alloc[0]/100:0;return {budget,spent,readiness,received,delivered:received*readiness,gap:Math.max(0,40-received*readiness)};}
 return {countries,fresh,position,valid,outcome};
})();
if(typeof module!=='undefined')module.exports=Lab;
